import java.util.*;import com.mojang.blaze3d.vertex.VertexConsumer;
/** Calibrates from the real attachment transform, clips in world coordinates, then returns to the same draw space. */
public final class Laser32{
 record Context(Object entity,double[] root){}static final ThreadLocal<Deque<Context>> CONTEXT=ThreadLocal.withInitial(ArrayDeque::new);static double[] view=Matrix32.identity();static Object world;static boolean warned;
 static double[] pose(Object stack){return Matrix32.read(R.call(R.call(stack,"last"),"pose"));}
 static double[] system(){return Matrix32.read(R.call(R.type("com.mojang.blaze3d.systems.RenderSystem"),"getModelViewMatrix"));}
 public static void stage(Object event){String stage=R.call(event,"getStage").toString();if(stage.toLowerCase(java.util.Locale.ROOT).matches(".*after_(sky|level)$")){view=Matrix32.read(R.call(event,"getModelViewMatrix"));world=R.get(BoxingClient16.mc(),"level");}}
 public static void begin(Object entity,Object stack){double[] root=pose(stack);CONTEXT.get().push(new Context(entity,root));}
 public static void end(){var s=CONTEXT.get();if(!s.isEmpty())s.pop();if(s.isEmpty())CONTEXT.remove();}
 static double ratio(){try{Class<?>c=R.type("com.tacz.guns.client.event.CameraSetupEvent");double a=R.num(R.call(R.get(c,"ITEM_MODEL_FOV_DYNAMICS"),"get")),b=R.num(R.call(R.get(c,"WORLD_FOV_DYNAMICS"),"get"));if(a>1&&a<179&&b>1&&b<179)return Math.tan(Math.toRadians(a/2))/Math.tan(Math.toRadians(b/2));}catch(IllegalStateException unavailable){}return 1;}
 static double[] mapping(double[] attachment,double[] root,boolean first,double[] mv,double fov){if(!first)return Matrix32.mul(Matrix32.inverse(root),attachment);double[] correction=Matrix32.identity();correction[10]=fov;return Matrix32.mul(Matrix32.inverse(view),Matrix32.mul(correction,Matrix32.mul(mv,attachment)));}
 static Object vec(double[]p){return R.make("net.minecraft.world.phys.Vec3",p[0],p[1],p[2]);}
 static double[] target(Object mc,Object entity){double[]eye=Matrix32.xyz(R.call(entity,"getEyePosition")),dir=Matrix32.xyz(R.call(entity,"getLookAngle"));Object hit=entity==R.get(mc,"player")?BoxingClient16.target(mc):null;if(hit!=null)try{double[]h=Matrix32.xyz(R.call(hit,"getLocation"));if("ENTITY".equals(R.call(hit,"getType").toString()))return h;double dx=h[0]-eye[0],dy=h[1]-eye[1],dz=h[2]-eye[2],n=Math.sqrt(dx*dx+dy*dy+dz*dz);if(n>.001)dir=new double[]{dx/n,dy/n,dz/n};}catch(IllegalStateException ignored){}return new double[]{eye[0]+dir[0]*256,eye[1]+dir[1]*256,eye[2]+dir[2]*256};}
 static double[] barrel(double[]origin,double[]base,double[]tip){double[]d={tip[0]-base[0],tip[1]-base[1],tip[2]-base[2]};double n=Math.sqrt(d[0]*d[0]+d[1]*d[1]+d[2]*d[2]);if(n<1e-8)throw new IllegalArgumentException("degenerate laser axis");return new double[]{origin[0]+d[0]*256/n,origin[1]+d[1]*256/n,origin[2]+d[2]*256/n};}
 static boolean foliage(Object state){try{if(R.yes(R.call(state,"canBeReplaced")))return true;Object block=R.call(state,"getBlock");for(Class<?> c=block.getClass();c!=null;c=c.getSuperclass()){String n=c.getSimpleName();if(n.equals("BushBlock")||n.equals("VegetationBlock")||n.equals("LeavesBlock")||n.equals("VineBlock")||n.equals("GrowingPlantBlock")||n.equals("SugarCaneBlock")||n.equals("BambooStalkBlock"))return true;}}catch(IllegalStateException missing){}return false;}
 static double[] clip(Object entity,Object level,double[]start,double[]end){double dx=end[0]-start[0],dy=end[1]-start[1],dz=end[2]-start[2],distance=Math.sqrt(dx*dx+dy*dy+dz*dz);if(distance<.0001)return start.clone();double max=Math.min(256,distance);dx/=distance;dy/=distance;dz/=distance;double[]finish={start[0]+dx*max,start[1]+dy*max,start[2]+dz*max},cursor=start.clone();for(int attempt=0;attempt<128;attempt++){Object ctx=R.make("net.minecraft.world.level.ClipContext",vec(cursor),vec(finish),R.get(R.type("net.minecraft.world.level.ClipContext$Block"),"COLLIDER"),R.get(R.type("net.minecraft.world.level.ClipContext$Fluid"),"NONE"),entity);Object hit=R.call(level,"clip",ctx);if(!"BLOCK".equals(R.call(hit,"getType").toString()))return finish;double[]h=Matrix32.xyz(R.call(hit,"getLocation"));Object bp=null;boolean skip=false;try{bp=R.call(hit,"getBlockPos");skip=foliage(R.call(level,"getBlockState",bp));}catch(IllegalStateException unavailable){}if(!skip){double len=Math.sqrt(Math.pow(h[0]-start[0],2)+Math.pow(h[1]-start[1],2)+Math.pow(h[2]-start[2],2));return new double[]{start[0]+dx*Math.max(0,len-.003),start[1]+dy*Math.max(0,len-.003),start[2]+dz*Math.max(0,len-.003)};}double[]cell=Matrix32.xyz(bp);double t=Double.POSITIVE_INFINITY;double[]dir={dx,dy,dz};for(int i=0;i<3;i++)if(Math.abs(dir[i])>1e-9)t=Math.min(t,((dir[i]>0?cell[i]+1:cell[i])-h[i])/dir[i]);if(!Double.isFinite(t)||t<-.001)return h;for(int i=0;i<3;i++)cursor[i]=h[i]+dir[i]*(Math.max(0,t)+.005);double traveled=(cursor[0]-start[0])*dx+(cursor[1]-start[1])*dy+(cursor[2]-start[2])*dz;if(traveled>=max)return finish;}return cursor;}
 // Clip in draw space before emitting a quad; a point behind the near plane must never become a screen-sized polygon.
 static double[][] nearSegment(double[]m,double[]end){double[]a=Matrix32.point(m,0,0,0),b=Matrix32.point(m,end[0],end[1],end[2]);double plane=-.08;if(a[2]>=plane&&b[2]>=plane)return null;double lo=0,hi=1;if(a[2]>=plane)lo=(plane-a[2])/(b[2]-a[2]);if(b[2]>=plane)hi=(plane-a[2])/(b[2]-a[2]);return new double[][]{{end[0]*lo,end[1]*lo,end[2]*lo},{end[0]*hi,end[1]*hi,end[2]*hi}};}
 static boolean nvg(Object p){try{return R.yes(R.call(p,"hasEffect",R.get(R.type("net.minecraft.world.effect.MobEffects"),"NIGHT_VISION")));}catch(IllegalStateException absent){return false;}}
 public static boolean render(Object stack,Object poses,Object context,Object path){boolean pushed=false;try{boolean first=R.yes(R.call(context,"firstPerson"));if(!first&&!context.toString().equals("THIRD_PERSON_RIGHT_HAND"))return true;Object mc=BoxingClient16.mc(),level=R.get(mc,"level");if(level==null||R.get(mc,"screen")!=null)return true;Context capture=CONTEXT.get().peek();Object entity=first?R.get(mc,"player"):capture==null?null:capture.entity();if(entity==null||!R.type("net.minecraft.world.entity.LivingEntity").isInstance(entity))return true;if(world!=level){view=Matrix32.identity();world=level;}Object camera=R.call(R.get(mc,"gameRenderer"),"getMainCamera");double[]cam=Matrix32.xyz(R.call(camera,"getPosition"));R.call(poses,"pushPose");pushed=true;for(Object part:(List<?>)path)R.call(part,"translateAndRotateAndScale",poses);double[]matrix=pose(poses),a=mapping(matrix,first?null:capture.root(),first,first?system():null,first?ratio():1),origin=Matrix32.point(a,0,0,0);for(int i=0;i<3;i++)origin[i]+=cam[i];double[]tip=Matrix32.point(a,0,0,-1),base=Matrix32.point(a,0,0,0);double[]end=clip(entity,level,origin,barrel(origin,base,tip));for(int i=0;i<3;i++)end[i]-=cam[i];double[]local=Matrix32.point(Matrix32.inverse(a),end[0],end[1],end[2]);Class<?> beam=R.type("com.tacz.guns.client.model.functional.BeamRenderer");Object cfg=R.call(beam,"getLaserConfig",stack);int color=((Number)R.call(R.type("com.tacz.guns.util.LaserColorUtil"),"getLaserColor",stack,cfg)).intValue();double width=Math.max(.002,Math.min(.012,R.num(R.call(cfg,first?"getWidth":"getWidthThird"))));Object source=R.call(R.call(mc,"renderBuffers"),"bufferSource");Object type=R.call(R.type("com.tacz.guns.client.model.functional.BeamRenderer$LaserBeamRenderState"),"getLaserBeam");VertexConsumer v=(VertexConsumer)R.call(source,"getBuffer",type);draw(v,matrix,local,width,color,nvg(R.get(mc,"player")),first);R.call(source,"endBatch",type);return true;}catch(RuntimeException failure){if(!warned){warned=true;System.err.println("[GlobalMelee32] Laser calibration failed: "+failure);}return false;}finally{if(pushed)R.call(poses,"popPose");}}
 public static Object texture(Object original){return R.call(R.type("net.minecraft.resources.ResourceLocation"),"fromNamespaceAndPath","zomboid_global_melee","textures/entity/laser32.png");}
 static int intensity(int c,double f){return (int)((c>>16&255)*f)<<16|(int)((c>>8&255)*f)<<8|(int)((c&255)*f);}
 static void vertex(VertexConsumer v,double[]m,double[]p,int color,int alpha,float u,float uv){double[]t=Matrix32.point(m,p[0],p[1],p[2]);v.addVertex((float)t[0],(float)t[1],(float)t[2]).setColor(color>>16&255,color>>8&255,color&255,alpha).setUv(u,uv).setUv2(240,240);}
 static void quad(VertexConsumer v,double[]m,double[]a,double[]b,double[]c,double[]d,int color,int alpha){vertex(v,m,a,color,alpha,0,0);vertex(v,m,b,color,alpha,0,1);vertex(v,m,c,color,alpha,1,1);vertex(v,m,d,color,alpha,1,0);}
 static double[] add(double[]a,double[]b,double scale){return new double[]{a[0]+b[0]*scale,a[1]+b[1]*scale,a[2]+b[2]*scale};}
 static void draw(VertexConsumer v,double[]m,double[]end,double width,int color,boolean night){draw(v,m,end,width,color,night,false);}
 static void draw(VertexConsumer v,double[]m,double[]end,double width,int color,boolean night,boolean first){double[][]segment=first?nearSegment(m,end):new double[][]{new double[]{0,0,0},end};if(segment==null)return;double[]origin=segment[0];boolean dot=!first||Matrix32.point(m,end[0],end[1],end[2])[2]<-.30;end=segment[1];double len=Math.sqrt(end[0]*end[0]+end[1]*end[1]+end[2]*end[2]);if(len<.001)return;double[]dir={end[0]/len,end[1]/len,end[2]/len},u=Math.abs(dir[1])<.9?new double[]{-dir[2],0,dir[0]}:new double[]{0,dir[2],-dir[1]};double n=Math.sqrt(u[0]*u[0]+u[1]*u[1]+u[2]*u[2]);for(int i=0;i<3;i++)u[i]/=n;double[]w={dir[1]*u[2]-dir[2]*u[1],dir[2]*u[0]-dir[0]*u[2],dir[0]*u[1]-dir[1]*u[0]},zero=origin;for(double[]axis:new double[][]{u,w}){quad(v,m,add(zero,axis,-width),add(zero,axis,width),add(end,axis,width),add(end,axis,-width),intensity(color,night?.65:.30),251);quad(v,m,add(zero,axis,-width*.30),add(zero,axis,width*.30),add(end,axis,width*.30),add(end,axis,-width*.30),color,251);}if(!dot)return;double size=width*(night?3:2);quad(v,m,add(add(end,u,-size),w,-size),add(add(end,u,-size),w,size),add(add(end,u,size),w,size),add(add(end,u,size),w,-size),color,251);}
}
